def cases():
    result = []
    for number, (record, context) in enumerate(zip(DATA, CONTEXT), 25):
        title, category, classification, origin, port, target, first, second, third, contrast, judgement, next_check = record
        hostname, account, hour, sessions, pivot = context
        start = datetime(2025, 3, 3 + (number - 25) % 7, hour, number % 20, tzinfo=timezone(timedelta(hours=9)))
        def stamp(offset):
            return (start + timedelta(seconds=offset)).isoformat()
        src = f'10.80.{number}.15'
        control_port = 80 if port == 443 else 443
        traffic = [(0, f'10.81.{number}.90', control_port, 280, 420)] + [(s, target, port, tx, rx) for s, tx, rx in sessions]
        events = [dict(source='fw', time=stamp(s), src=src, dst=ip, sport=46000+number*10+i,
                       dport=p, proto='UDP' if p == 123 else 'TCP', action='allow', sent=tx, rcvd=rx, duration=1+i)
                  for i, (s, ip, p, tx, rx) in enumerate(traffic)]
        trigger = f'{origin}. 조사 대상은 {hostname}({src})이다.'
        offsets = {25:(-1,3,1800),26:(7,8,1800),27:(-60,3,1800),28:(4,18,25),29:(-900,4,85),30:(7,3,600),31:(4,-86400,7),32:(4,-1800,3),33:(-3,3,600),34:(-60,0,3),35:(-600,0,3),36:(-60,4,95),37:(45,-86400,46),38:(8,-86400,12),39:(-3,3,900),40:(-600,-8,900),41:(-60,26,1200),42:(-900,4,20)}[number]
        followups = []
        for i, ((source, k, v), offset) in enumerate(zip((first, second, third), offsets), 1):
            fields = dict(time=stamp(offset), subject_host=hostname, subject_ip=src, account=account,
                          peer_ip=target, **{k:v})
            hash_rows = {25:(1,3),28:(1,3),33:(1,3),35:(2,3),36:(2,3),39:(1,3)}
            if i in hash_rows.get(number, ()):
                fields['sha256'] = sha256(f'synthetic-investigation-sample-{number}'.encode()).hexdigest()
            followups.append(dict(id=f'W{number}-E{i}', source=source, fields=fields))
        result.append(dict(id=f'W{number}', title=title, classification=classification, category=category,
                           trigger=trigger, pivot=pivot, comparison=contrast, judgement=judgement,
                           next_check=next_check, events=events, followups=followups,
                           lead=dict(source='fw',field='src_ip',value=src,basis=trigger),
                           narrow=[dict(field='dst_port',op='is',value=port)],
                           narrow_reason=f'{target}의 {port}번 세션을 조사한다. {pivot}'))
    return result
